-- ============================================
-- LUMA — Thème 15 : MOYEN 1/3 x4 — Une journée touristique avec plusieurs arrêts et choix d'itinéraire
-- ============================================


update scenarios set content = '{"characters": {"alice": "Alice"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alice", "text": "Okay, we have one full day to see London. Where should we start?", "text_fr": "Bon, on a une journée entière pour voir Londres. On commence où ?", "choices": [{"text": "Let''s start with Big Ben and Westminster, get the iconic stuff first.", "text_fr": "Commençons par Big Ben et Westminster, les trucs iconiques en premier.", "next": "n2"}, {"text": "How about the British Museum first, before it gets crowded?", "text_fr": "Et si on faisait le British Museum d''abord, avant que ça se remplisse ?", "next": "n2b"}]}, "n2": {"speaker": "alice", "text": "Good call, those photos will be perfect in the morning light.", "text_fr": "Bonne idée, ces photos seront parfaites avec la lumière du matin.", "choices": [{"text": "Exactly what I was thinking. Let''s head there now.", "text_fr": "Exactement ce que je pensais. Allons-y maintenant.", "next": "n3"}]}, "n2b": {"speaker": "alice", "text": "Smart thinking, that museum gets packed by midday.", "text_fr": "Pensée intelligente, ce musée se remplit d''ici midi.", "choices": [{"text": "Let''s make that our first stop then.", "text_fr": "Faisons-en notre premier arrêt alors.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(After your first stop, you check the time — already past noon.)", "text_fr": "(Après votre premier arrêt, vous vérifiez l''heure — déjà passé midi.)", "choices": [{"text": "We should grab lunch before continuing to our next stop.", "text_fr": "On devrait déjeuner avant de continuer vers notre prochain arrêt.", "next": "n4"}, {"text": "Let''s push on to Tower Bridge, we can eat later.", "text_fr": "Continuons vers Tower Bridge, on mangera plus tard.", "next": "n4b"}]}, "n4": {"speaker": "alice", "text": "Good idea, there''s a nice market nearby with quick options.", "text_fr": "Bonne idée, il y a un chouette marché à proximité avec des options rapides.", "choices": [{"text": "Perfect, let''s refuel there.", "text_fr": "Parfait, refaisons le plein là-bas.", "next": "n5"}]}, "n4b": {"speaker": "alice", "text": "I''m a bit hungry, but I can push through if you want to keep the momentum.", "text_fr": "J''ai un peu faim, mais je peux tenir si tu veux garder l''élan.", "choices": [{"text": "Actually, let''s stop for a quick bite, you shouldn''t go hungry.", "text_fr": "En fait, arrêtons-nous pour manger un morceau vite, tu devrais pas rester sur ta faim.", "next": "n5"}]}, "n5": {"speaker": "alice", "text": "So, Tower Bridge next, or should we squeeze in Camden Market too?", "text_fr": "Donc, Tower Bridge ensuite, ou on devrait aussi caser Camden Market ?", "choices": [{"text": "Both sound amazing, but let''s prioritize Tower Bridge given the time.", "text_fr": "Les deux ont l''air géniaux, mais priorisons Tower Bridge vu l''heure.", "next": "n6"}, {"text": "Let''s try to fit both in, we can move quickly.", "text_fr": "Essayons de caser les deux, on peut bouger vite.", "next": "n6b"}]}, "n6": {"speaker": "alice", "text": "Good call, quality over quantity for the rest of today.", "text_fr": "Bonne idée, la qualité plutôt que la quantité pour le reste d''aujourd''hui.", "choices": [{"text": "Exactly, let''s really enjoy Tower Bridge without rushing.", "text_fr": "Exactement, profitons vraiment de Tower Bridge sans se presser.", "next": "n7"}]}, "n6b": {"speaker": "alice", "text": "Ambitious, but let''s go for it! We can always cut something if we''re running late.", "text_fr": "Ambitieux, mais allons-y ! On peut toujours couper quelque chose si on est en retard.", "choices": [{"text": "Agreed, let''s move efficiently between the two.", "text_fr": "D''accord, déplaçons-nous efficacement entre les deux.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(By evening, exhausted but happy, you both reflect on a jam-packed day.)", "text_fr": "(Le soir venu, épuisés mais heureux, vous réfléchissez tous les deux à une journée bien remplie.)", "choices": [{"text": "What a day! I think we really made the most of our time.", "text_fr": "Quelle journée ! Je pense qu''on a vraiment profité de notre temps au maximum.", "next": "end_fullday"}]}, "end_fullday": {"speaker": "alice", "text": "Absolutely, this might be one of my favorite days of the whole trip.", "text_fr": "Absolument, ça pourrait bien être l''un de mes jours préférés de tout le voyage.", "end": true, "ending_label": "Journée touristique complète et bien organisée 🎡🗺️"}}}'::jsonb, is_playable = true
where title = 'Une journée touristique avec plusieurs arrêts et choix d''''itinéraire'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
